The integrated FB asymmetry from Eq.~\ref{FB1-1} is shown in Fig.~\ref{AFB-2} for $M_{Z^\prime}=7.5$ TeV as a function of $\sqrt{s}$ for $\mu^+ \mu^-$ (top panel), $b\overline{b}$ (middle panel) and $t\overline{t}$ (bottom panel). We consider three combinations of polarizations for the $e^-$ and $e^+$ as before. Taking $x_H=-2$, $-1$, $1$ and $2$ we compare $\mathcal{A}_{\rm{FB}}$ in presence of $Z^\prime$ with that in the SM. In this analysis $\mathcal{A}_{\rm FB}$ is an important observable in $s$-channel scattering. For different choices of $x_H$,  $\mathcal{A}_{\rm{FB}}$ contains BSM effect from $q^{\rm{XY}}$ according to Table~\ref{tabASM}. These are clearly affected by the choice of $x_H$. For $e^-e^+ \to \mu^+ \mu^-$, the integrated FB asymmetries for $x_H=-2$ and $-1$ can be respectively written as 

\begin{figure}[t!]
\begin{center}
\includegraphics[scale=0.55]{FIG10.pdf} 








\caption{The integrated FB asymmetry for different choices of $x_H$ as a function of the center of mass energy for $e^-e^+ \to f \overline{f}$ process with $\mu^+\mu^-$ (top row), $b\overline{b}$ (middle row) and $t\overline{t}$ (bottom row). The columns correspond to three sets of polarizations of incoming electron and positron beams. We have chosen $M_{Z^\prime}=7.5$ TeV and $g^\prime=0.4$. The SM result is shown by the solid black line in each case.}
\label{AFB-2}
\end{center}
\end{figure}

\begin{align}
\mathcal{A}_{\rm FB}^{x_H=-2}(P_{e^-},P_{e^+}) \simeq \frac{3}{4}\frac{(1+P_{\rm eff}) \{|q^{e_{R} \mu_{R}}|^{2}-|q^{e_R \mu_L}_{\rm{SM}}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2}-|q^{e_L f_R}_{\rm{SM}}|^2 \}}{(1+P_{\rm eff}) \{|q^{e_{R} \mu_{R}}|^{2}+|q^{e_R \mu_L}_{\rm{SM}}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2}+|q^{e_L \mu_R}_{\rm{SM}}|^2 \}},\,
\label{AFB1-1a}
\\
\mathcal{A}_{\rm FB}^{x_H=-1}(P_{e^-},P_{e^+}) \simeq  \frac{3}{4}\frac{(1+P_{\rm eff}) \{|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2}-|q^{e_R \mu_L}_{\rm{SM}}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} \mu_{L}}|^{2}-|q^{e_L \mu_R}_{\rm{SM}}|^2 \}}{(1+P_{\rm eff}) \{|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2}+|q^{e_R f_L}_{\rm{SM}}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} \mu_{L}}|^{2}+|q^{e_L \mu_R}_{\rm{SM}}|^2 \}}.
\label{AFB1-1}
\end{align}

For other $x_H$ values, the BSM effects come from all $q^{\rm{XY}}$ combinations. In Eqs.~\ref{AFB1-1a} and \ref{AFB1-1}, the term SM denotes the SM effects from $\{Z, \gamma\}$ and the corresponding interferences with the BSM. Note that for $x_H=-2$ and $-1$ the BSM effect in $\mathcal{A}_{\rm{FB}}$ is small for $\mu^-\mu^+$ process compared to the SM (represented by solid black line) in the top panel of Fig.~\ref{AFB-2}. For the other two charges $x_H=1$ and $2$, $\mathcal{A}_{\rm{FB}}$ is comparatively higher than the SM result due to the effects of all $q^{\rm{XY}}$ for different polarizations. $\mathcal{A}_{\rm{FB}}$ depends on the quantities $(1-P_{\rm{eff}})$ and $(1+P_{\rm{eff}})$ which will be either greater or less than 1; however, for our choice of non-zero polarizations $(1-P_{\rm{eff}})$ and $(1+P_{\rm{eff}})$ are always positive. Depending on the choice of $x_H$, $\mathcal{A}_{\rm{FB}}$ could be greater or less than the results of SM. 

For the $e^-e^+ \to b\overline{b}$ process, we notice that for $x_H=-1$ the BSM contributions come from $q^{{LL}}$ and $q^{{LR}}$  in the FB asymmetry, whereas for $x_H=1$ the BSM contributions come from $q^{{LL}}$ and $q^{{RL}}$. The expressions for these charges can be written as 
\begin{align}
\mathcal{A}_{\rm FB}^{x_H=-1}(P_{e^-},P_{e^+}) \simeq \frac{3}{4}\frac{(1+P_{\rm eff}) \{|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}-|q^{e_R b_L}_{\rm{SM}}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} b_{L}}|^{2}-|q^{e_L f_R}|^2 \}}{(1+P_{\rm eff}) \{|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}+|q^{e_R b_L}_{\rm{SM}}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} b_{L}}|^{2}+|q^{e_L b_R}|^2 \}} \, ,  \\
\mathcal{A}_{\rm FB}^{x_H=1}(P_{e^-},P_{e^+}) \simeq  \frac{3}{4}\frac{(1+P_{\rm eff}) \{|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}-|q^{e_R b_L}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} b_{L}}|^{2}-|q^{e_L b_R}_{\rm{SM}}|^2 \}}{(1+P_{\rm eff}) \{|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}+|q^{e_R b_L}|^2 \}+ (1-P_{\rm eff}) \{|q^{e_{L} b_{L}}|^{2}+|q^{e_L b_R}_{\rm{SM}}|^2 \}}.
\label{AFB1-2}
\end{align}

In this case $x_H=-2$ will affect the interaction between electron and $Z^\prime$ which will be reflected in the nature of $\mathcal{A}_{\rm{FB}}$. The nature of the asymmetries for $b\overline{b}$ process is shown in the middle panels of Fig.~\ref{AFB-2} for all $x_H$ and different polarizations. For the top quark pair production all $q^{\rm{XY}}$ contribute for $x_H=2$. Rest of the contributions can be obtained from Eqs.~\ref{AFB1-1a}-\ref{AFB1-2} depending on $x_H$ values. The nature of the FB asymmetry for $t\overline{t}$ process is shown in the bottom panels of Fig.~\ref{AFB-2} for different values of $x_H$ and different sets of polarizations. 

\begin{sidewaysfigure}
\begin{center}
\includegraphics[scale=0.75]{FIG11.pdf} 










\caption{The deviation in the integrated FB asymmetry as a function of $P_{e^-}$ for $e^-e^+ \to f \overline{f}$ process taking $P_{e^+}=0$ for $M_{Z^\prime}=7.5$ TeV.  The theoretically estimated statistical error has been represented by the gray-shaded band. The integrated luminosity is taken to be $\mathcal{L}_{\rm{int}}=1$ ab$^{-1}$.}
\label{DevAFB-2}
\end{center}
\end{sidewaysfigure}


The deviation of the FB asymmetry from the SM result can be defined as 
\begin{align}
 \Delta_{\mathcal{A}_{\rm FB}} \ = \ \frac{\mathcal{A}_{\rm FB}^{U(1)_X}}{\mathcal{A}_{\rm FB}^{\rm SM}}-1 \, .
\label{DAFB}
\end{align}
$\Delta_{\mathcal{A}_{\rm{FB}}}$ is shown in Fig.~\ref{DevAFB-2} for $\mu^-\mu^+$ (top panel), $b\overline{b}$ (middle panel) and $t\overline{t}$ (bottom panel) using $M_{Z^\prime}=7.5$ TeV and  keeping $P_{e^+}=0$, while varying $P_{e^-}$  from 0 to 1. The theoretically estimated statistical error represented by gray-shaded band has been calculated as
\bea
 \Delta \mathcal{A}^{\rm stat}_{\rm FB} & \ = \ &



\frac{2\sqrt{N_F N_B}}
 {(N_F + N_B)
 \left(\sqrt{N_F}-\sqrt{N_B}\right)} \, 
\mathcal{A}_{\rm FB}
\label{StatAFB}
\eea
where 
$N_{F(B)}= {\cal L}_{\rm int} \sigma_{F(B)}(P_{e^-},P_{e^+})$ is the number of events in the forward (backward) direction. The different columns correspond to $\sqrt{s}=250$ GeV (except for $t\overline{t}$), $500$ GeV, $1$ TeV and $3$ TeV. The nature of the deviations shown here can be understood from Eqs.~\ref{AFB1-1a}-\ref{AFB1-2}. The BSM contributions in differential FB asymmetry for different fermions for different $x_H$ are guided by Table~\ref{tabASM}.

We find that at $\sqrt{s}=250$ GeV the deviations in FB asymmetry from the SM in case of $\mu^-\mu^+$ is less than $1\%$ for all $x_H$. For all $\sqrt{s}$, the cases $x_H=-2$ and $-1$ are within the theoretically estimated statistical error. Even for $\sqrt s=3$ TeV and  $P_{e^-}=0.8$ the deviation is roughly $3\%$ for $x_H=-2$. 
In case of $\sqrt{s}=500$ GeV for $P_{e^-}=-0.8$ the deviation is $1.9\%$ and that for $P_{e^+}=0.8$ is $1.8\%$ for $x_H=1$. The deviations for $x_H=2$ are $3.9\%$ and $3.4\%$ for $P_{e^-}=-0.8$ and $P_{e^+}=0.8$ respectively. The deviation for $x_H=-2$ is nearly $2\%$ for $P_{e^-}=0.8$ at $\sqrt{s}=1$ TeV. For $x_H=1$ the deviations are $8\%$ and $7\%$ for $P_{e^-}=-0.8$ and $P_{e^+}=0.8$ respectively at $\sqrt{s}=1$ TeV. At $\sqrt{s}=1$ TeV the deviation for $x_H=2$ at $P_{e^-}=-0.8$ is roughly $16.5\%$ and at $P_{e^-}=0.8$ the deviation is roughly $13\%$. The deviations for $x_H=2$ and $1$ at $\sqrt{s}=3$ TeV are very large compared to the other choices of $\sqrt{s}$. 

Studying the $b\overline{b}$ process we find the deviation is small at $\sqrt{s}=250$ GeV for $P_{e^-}=-0.8$ and the deviation at $P_{e^-}=0.8$ is around $2\%$ for $x_H=2$. The deviation at $P_{e^-}=0.8$ is below $2\%$ for $x_H=-2$. For $x_H=1$ and $x_H=2$ the deviations are around $3\%$ and $5.5\%$ respectively for $\sqrt{s}=500$ GeV at $P_{e^-}=0.8$. The deviations for $x_H=-2$, $1$ and $2$ are enhanced by orders of magnitude at $\sqrt{s}=1$ TeV and $3$ TeV. In case of $t\overline{t}$ we notice that the deviation is large at $P_{e^-}=-0.8$ for different $x_H$. At $\sqrt{s}=500$ GeV the deviations are roughly $3\%$ for $x_H=2$ and $1.4\%$ for $x_H=1$. The deviations increase with $\sqrt{s}$ by some factor up to an order of magnitude depending on $x_H$ and $P_{e^-}$. 

\subsection{Differential left-right asymmetry $(\mathcal{A}_{\rm{LR}}(\cos\theta))$}

The left-right (LR) asymmetry $(\mathcal{A}_{\rm LR})$ is another important observable which can be tested at the $e^-e^+$ colliders~\cite{Schrempp:1987zy,Kennedy:1988rt,MoortgatPick:2005cw,Baak:2013fwa,ALEPH:2005ab}. The differential $\mathcal{A}_{\rm LR}$ is given by 
\bea
\mathcal{A}_{\rm LR} (\cos\theta) \ = \ \frac{\frac{d\sigma_{\rm LR}}{d\cos\theta}(\cos\theta)-\frac{d\sigma_{\rm RL}}{d\cos\theta}(\cos\theta)}{\frac{d\sigma_{\rm LR}}{d\cos\theta}(\cos\theta)+\frac{d\sigma_{\rm RL}}{d\cos\theta}(\cos\theta)} \, , 
\label{ALR-d-A}
\eea
where $\frac{d\sigma_{\rm LR}}{d\cos\theta}$ and $\frac{d\sigma_{\rm RL}}{d\cos\theta}$ are given in Eqs.~\ref{Xsec1-x2} and \ref{Xsec1-x1} respectively. 
For $m_f \ll \sqrt{s}$, Eq.~\ref{ALR-d-A} reduces to 
\begin{align}
{\cal A}_{\rm LR}(\cos\theta)
 &\ \simeq \ \frac{(1+\cos\theta)^2
 \left(|q^{e_{L} f_{L}}|^{2}-|q^{e_{R} f_{R}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} f_{R}}|^{2}-|q^{e_{R} f_{L}}|^{2}\right)
}
{(1+\cos\theta)^2
 \left(|q^{e_{L} f_{L}}|^{2}+|q^{e_{R} f_{R}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} f_{R}}|^{2}+|q^{e_{R} f_{L}}|^{2}\right)
 } \, .
\label{ALR-d-no-mf-1} 
\end{align}
The observable differential $\mathcal{A}_{\rm LR}$ in terms of the $e^\pm$ polarizations can be written as 
\begin{align}
\mathcal{A}_{\rm LR}(P_{e^-},P_{e^+},\cos\theta)
& \ = \  \frac{
 \frac{d\sigma}{d\cos\theta}(P_{e^-},P_{e^+},\cos\theta)
 -\frac{d\sigma}{d\cos\theta}(-P_{e^-},-P_{e^+},\cos\theta)
 }
 {
\frac{d\sigma}{d\cos\theta}(P_{e^-},P_{e^+},\cos\theta)
 +\frac{d\sigma}{d\cos\theta}(-P_{e^-},-P_{e^+},\cos\theta)
 } \, .
\label{A_LR-cos-obs}
\end{align}
for $P_{e^-}<0$ and $|P_{e^-}|>|P_{e^+}|$. Hence we find that 
Eq.~\ref{A_LR-cos-obs} is related to Eq.~\ref{ALR-d-no-mf-1} by
\begin{align}
\mathcal{A}_{\rm LR}(\cos\theta) \ = \ \frac{1}{P_{\rm eff}}
\mathcal{A}_{\rm LR}(P_{e^-},P_{e^+},\cos\theta) ~.
\label{A_LR_cos}
\end{align}


\begin{sidewaysfigure}
\begin{center}
\includegraphics[scale=0.75]{FIG12.pdf} 










\caption{The differential LR asymmetry for $e^-e^+ \to f \overline{f}$ process as a function of $\cos\theta$ for $M_{Z^\prime}=7.5$ TeV. The contribution from the SM has been represented by the black solid line. }
\label{ALRtheta-2}
\end{center}
\end{sidewaysfigure}


The nature of differential LR asymmetry from Eq.~\ref{A_LR-cos-obs} is shown in Fig.~\ref{ALRtheta-2} for $\mu^+\mu^-$ (top panel), $b\overline{b}$ (middle panel) and $t\overline{t}$ (bottom panel) using $M_{Z^\prime}=7.5$ TeV as a function of $\cos\theta$ for $\sqrt{s}=250$ GeV (except $t \overline{t}$), $500$ GeV, $1$ TeV and $3$ TeV respectively. We estimate the asymmetry parameter for the $U(1)_X$ scenario considering $x_H=-2$, $-1$, $1$ and $2$ and present them along with the SM result (solid black line). The LR asymmetry depends on $x_H$ through the interactions between the charged fermions and $Z^\prime$ as shown in Table~\ref{tabASM}. According to that, the differential LR asymmetry for $x_H=-2$ and $-1$ for the $e^-e^+ \to \mu^+ \mu^-$ process from Eq.~\ref{ALR-d-no-mf-1} can be written as 
