\subsection{Integrated left-right asymmetry (${\cal A}_{\rm LR}$)} 

We also calculate the integrated $\mathcal{A}_{\rm{LR}}$ by integrating Eq.~\ref{ALR-d-A} over the scattering angle: 
\begin{align}
 \mathcal{A}_{\rm LR}
 & \ = \ \frac{\sigma^{\rm LR}-\sigma^{\rm RL}}
 {\sigma^{\rm LR}+ \sigma^{\rm RL}}.
\label{ALRx}
\end{align}
In terms of the gauge couplings of the fermions, we can write Eq.~\ref{ALRx} as
\bea
 \mathcal{A}_{\rm LR} 
 \ = \ \frac{\splitfrac{\Big( 1 + \frac{1}{3}\beta^{2} \Big) 
 \Big[  \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2} \big)
 -  \big( |q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2} \big) \Big]}{
 + 8 \frac{m_{f}^{2}}{s} \Big[ {\rm Re}(q^{e_{L}f_{L}} {q^{e_{L} f_{R}}}^{\ast})
- {\rm Re}( q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{\ast}) \Big]}}{\splitfrac{\Big( 1 + \frac{1}{3}\beta^{2} \Big) 
 \Big[  \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2} \big)
 +  \big( |q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2} \big) \Big]}{ + 8 \frac{m_{f}^{2}}{s} \Big[ {\rm Re}(q^{e_{L}f_{L}} {q^{e_{L} f_{R}}}^{\ast})
+ {\rm Re}( q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{\ast}) \Big]}} \, .
\label{Eq:A_LR-Qs}
\eea
In the limit $m_{f} \ll \sqrt{s}$, Eq.~\ref{Eq:A_LR-Qs} is reduced to
\begin{align}
 \mathcal{A}_{\rm LR}
 & \ \simeq \  
\frac{
(|q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2})
 - (|q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2})
}{
(|q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2})
 + (|q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2})
} \, .
\label{ALR-No-mf}
\end{align}
The observable integrated $\mathcal{A}_{\rm{LR}}$ as a function of the electron and positron beam polarizations is given by 
\begin{align}
\mathcal{A}_{\rm LR}(P_{e^-},P_{e^+})
\  = \  \frac{
 \sigma(P_{e^-},P_{e^+})
 -\sigma(-P_{e^-},-P_{e^+})
 }
 {
 \sigma(P_{e^-},P_{e^+})
 +\sigma(-P_{e^-},-P_{e^+})
 } \, ,
\label{ALR-obs}
\end{align}
for $P_{e^-}<0$ and $|P_{e^-}|>|P_{e^+}|$. This is related to Eq.~\ref{ALRx} by
\bea
\mathcal{A}_{\rm LR} \ = \ \frac{1}{P_{\rm eff}}
\mathcal{A}_{\rm LR}(P_{e^-},P_{e^+}) \, .
\label{difA}
\eea

